import {ToolRegistry} from './registry.js';
import {setLogger, type Logger} from '../../shared/logger.js';

describe('ToolRegistry input validation', () => {
  it('passes valid input and unlisted properties through unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', extra: 'keep me'};
    let received: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async value => {
        received = value;
        return 'sunny';
      }
    );

    await registry.execute('get_weather', input);

    expect(received).toEqual(input);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    const calls = {count: 0};
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: Object.freeze({
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        }),
      },
      async () => {
        calls.count += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls: calls.count,
      result: response.result,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      result: expect.any(String),
      mentionsRequiredField: true,
    });
  });

  it('rejects a wrong-typed property with its path and expected type without leaking the value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_record', {identifier: 123456789});

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
  validators: WeakMap<Record<string, unknown>, ValidateFunction>;
}

interface ValidationError {
  instancePath?: string;
  dataPath?: string;
  keyword?: string;
  params: Record<string, unknown>;
  message?: string;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileValidator(name: string, inputSchema: Record<string, unknown>): ValidateFunction {
    try {
      return new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]).compile(inputSchema);
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool '${name}': ${message}`, {cause: error});
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      validator = this.compileValidator(resolved.name, resolved.inputSchema);
    }
    this.tools.set(resolved.name, {
      definitionSource: definition,
      execute,
      validator,
      validators: new WeakMap(),
    });
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input against its schema; only an unknown tool name throws (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.validator ?? this.validatorFor(tool, definition);
    if (!validator(input)) {
      return this.invalidInput(name, validator.errors ?? []);
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): ValidateFunction {
    const cached = tool.validators.get(definition.inputSchema);
    if (cached) return cached;
    const validator = this.compileValidator(definition.name, definition.inputSchema);
    tool.validators.set(definition.inputSchema, validator);
    return validator;
  }

  private invalidInput(name: string, errors: ValidationError[]): ToolResponse {
    const messages = errors.map(error => {
      const path = this.errorPath(error);
      const missing = typeof error.params.missingProperty === 'string' ? ` '${error.params.missingProperty}'` : '';
      return `${path}${missing} ${error.message ?? 'is invalid'}`;
    });
    log.warn('tool', 'input validation failed', {
      name,
      paths: errors.map(error => this.errorPath(error)),
      constraints: errors.map(error => error.keyword ?? 'unknown'),
    });
    return {result: `Tool '${name}' input invalid: ${messages.join('; ')}`};
  }

  private errorPath(error: ValidationError): string {
    const path = error.instancePath || error.dataPath;
    if (!path) return '(root)';
    return path.startsWith('.') ? `/${path.slice(1).replaceAll('.', '/')}` : path;
  }
}
